PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_salt TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'seller' CHECK(role IN ('seller','admin')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS listings(id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL, category TEXT NOT NULL, condition TEXT NOT NULL, image_url TEXT NOT NULL, seller_id TEXT REFERENCES users(id) ON DELETE SET NULL, seller_name TEXT NOT NULL, listing_type TEXT NOT NULL CHECK(listing_type IN ('auction','fixed')), price_jmd INTEGER NOT NULL CHECK(price_jmd>0), start_price_jmd INTEGER, current_bid_jmd INTEGER, bid_increment_jmd INTEGER NOT NULL DEFAULT 100 CHECK(bid_increment_jmd>0), ends_at TEXT, stock INTEGER NOT NULL DEFAULT 1 CHECK(stock>=0), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','sold','ended','removed')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_listings_active ON listings(status,category,created_at DESC);
CREATE TABLE IF NOT EXISTS bids(id TEXT PRIMARY KEY, listing_id TEXT NOT NULL REFERENCES listings(id), bidder_id TEXT REFERENCES users(id) ON DELETE SET NULL, bidder_name TEXT NOT NULL, amount_jmd INTEGER NOT NULL CHECK(amount_jmd>0), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_bids_listing ON bids(listing_id,amount_jmd DESC,created_at DESC);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY, order_code TEXT NOT NULL UNIQUE, listing_id TEXT NOT NULL REFERENCES listings(id), buyer_name TEXT NOT NULL, buyer_email TEXT NOT NULL, amount_jmd INTEGER NOT NULL, payment_status TEXT NOT NULL DEFAULT 'unpaid', order_status TEXT NOT NULL DEFAULT 'placed', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
